const footer = {
  id:'footer',
  copy:{
    copyright: '©&nbsp;Old Mates Cranes & Rigging',
    by: ' – web design by carlosesierra.com.au'
  }
};

const Footer = () =>  (
    <section className='container-fluid p-0 bg-charcoal' id={footer.id}>
      <div className='row px-4 g-0'>
        <div className='col text-white'>
          {footer.copy.copyright}
          {footer.copy.by}
        </div>
      </div>
    </section>
)

export default Footer;
